from pysat.solvers import Solver as SATSolver
from pysat.card import CardEnc
import itertools

num_golfers = 35
num_weeks = 5
num_groups = 7
group_size = 5

# Variable encoding: v = w*35*7 + p*7 + g + 1 (1-indexed for SAT)
# x[w][p][g] = True iff golfer p is in group g in week w
def var(w, p, g):
    return w * num_golfers * num_groups + p * num_groups + g + 1

num_vars = num_weeks * num_golfers * num_groups
print(f"Number of variables: {num_vars}")

clauses = []

# Each golfer is in exactly one group per week
for w in range(num_weeks):
    for p in range(num_golfers):
        # At least one group
        clauses.append([var(w, p, g) for g in range(num_groups)])
        # At most one group
        for g1 in range(num_groups):
            for g2 in range(g1+1, num_groups):
                clauses.append([-var(w, p, g1), -var(w, p, g2)])

# Each group has exactly 5 golfers per week
for w in range(num_weeks):
    for g in range(num_groups):
        vars_list = [var(w, p, g) for p in range(num_golfers)]
        # Exactly 5
        enc = CardEnc.equals(lits=vars_list, bound=group_size, encoding=1)
        clauses.extend(enc.clauses)

print(f"Clauses after group constraints: {len(clauses)}")

# No pair meets more than once
for p1 in range(num_golfers):
    for p2 in range(p1+1, num_golfers):
        for w1 in range(num_weeks):
            for w2 in range(w1+1, num_weeks):
                for g in range(num_groups):
                    clauses.append([-var(w1, p1, g), -var(w1, p2, g), 
                                   -var(w2, p1, g), -var(w2, p2, g)])

print(f"Total clauses: {len(clauses)}")
